def sort_candidates(candidates):
    """按评分降序、投递时间升序排列候选人。"""
    return sorted(candidates, key=lambda item: -item["score"])

verification_tests:
from target import sort_candidates


def test_equal_score_is_ordered_by_submission_time():
    items = [
        {"name": "a", "score": 5, "submitted_at": 30},
        {"name": "b", "score": 5, "submitted_at": 10},
    ]
    assert [item["name"] for item in sort_candidates(items)] == ["b", "a"]


def test_higher_score_comes_first():
    items = [
        {"name": "a", "score": 1, "submitted_at": 10},
        {"name": "b", "score": 9, "submitted_at": 20},
    ]
    assert [item["name"] for item in sort_candidates(items)] == ["b", "a"]


def test_empty_input_returns_empty_list():
    assert sort_candidates([]) == []
